class Spider(Spider):
    def getName(self):
        return "py_4gtv2"

    def init(self, extend=""):
        pass

    def homeContent(self, filter):
        classes = [{"type_name": g, "type_id": g} for g in CHANNELS]
        return {"class": classes}

    def _vod(self, tid, i, name, logo):
        return {"vod_id": tid + "|" + str(i), "vod_name": name, "vod_pic": logo, "vod_remarks": tid}

    def categoryContent(self, tid, pg, filter, extend):
        vods = [self._vod(tid, i, n, lg) for i, (n, u, lg) in enumerate(CHANNELS.get(tid, []))]
        return {"page": 1, "pagecount": 1, "limit": len(vods), "total": len(vods), "list": vods}

    def detailContent(self, ids):
        vid = ids[0]
        tid, idx = vid.rsplit("|", 1)
        name, url, logo = CHANNELS[tid][int(idx)]
        vod = {"vod_id": vid, "vod_name": name, "vod_pic": logo,
               "vod_play_from": tid, "vod_play_url": "直播$" + vid}
        return {"list": [vod]}

    def playerContent(self, flag, id, vipFlags):
        tid, idx = id.rsplit("|", 1)
        name, url, logo = CHANNELS[tid][int(idx)]
        return {"parse": 0, "playUrl": "", "url": url, "header": {}}

    def searchContent(self, key, quick, pg="1"):
        vods = []
        for tid, items in CHANNELS.items():
            for i, (name, url, logo) in enumerate(items):
                if key in name:
                    vods.append(self._vod(tid, i, name, logo))
        return {"list": vods}

    def localProxy(self, param):
        pass

    def isVideoFormat(self, url):
        return False

    def manualVideoCheck(self):
        return False

    def homeVideoContent(self):
        return {"list": []}
